#!/usr/bin/env python3
"""Generates satdiff-plugin/src/params.rs (SatDiff parameters). Run from rust/: python3 tools/gen_dparams.py

Parameter ids are permanent once released. Slot numbers are the UI's addressing scheme; the sat module keeps SatComp's slot numbers (1-7, 25, 27, bypass 26, out gain 22) so the shared sat UI code addresses the same cells.
"""
P = []  # (slot, id, display name, kind, min, max, default, step, unit)
def add(n, i, name, kind, mn, mx, df, step=None, unit=""):
    P.append((n, i, name, kind, mn, mx, df, step, unit))

# SAT (the SatComp saturator module)
add(1, "shape", "Shape", "int", 0, 14, 0)
add(2, "drive", "Drive", "f", 0, 100, 0, 0.1, " %")
add(3, "bias", "Bias", "f", -100, 100, 0, 0.1, " %")
add(4, "sat_hp", "Sat HP", "f", 20, 2000, 20, 1, " Hz")
add(5, "sat_lp", "Sat LP", "f", 200, 20000, 20000, 1, " Hz")
add(6, "tone", "Tone", "f", 1000, 20000, 20000, 1, " Hz")
add(7, "os", "Oversampling", "int", 0, 3, 0)          # x1 x2 x4 x8: saturator and clipper
add(25, "sat_mix", "Sat Mix", "f", 0, 100, 100, 1, " %")
add(27, "in_gain", "In Gain", "f", -24, 24, 0, 0.1, " dB")        # first in the chain (the dry IN meter reads before it)
# OUT
add(22, "out_gain", "Out Gain", "f", -24, 12, 0, 0.1, " dB")  # after the sat section, before the limiter
add(23, "gain_match", "Gain Match", "bool", 0, 1, 0)
add(24, "lim_on", "Limiter", "bool", 0, 1, 1)                  # true-peak output limiter (the plug-in default is on)
add(26, "bypass", "Bypass", "bool", 0, 1, 0)
# PHASE SECTION, tile, scenes, morph: UI only until the matching DSP step lands
add(30, "phase", "Phase", "f", -180, 180, 0, 1, " deg")
add(31, "fx_on", "FX On", "bool", 0, 1, 0)
add(32, "fx_type", "FX Type", "int", 0, 4, 0)
add(33, "fx_pos", "FX Pre/Post", "int", 0, 1, 0)
add(34, "fx_freq", "FX Freq", "f", 20, 20000, 1000, 1, " Hz")
add(35, "fx_q", "FX Q", "f", 0.3, 8, 0.7, 0.01, "")
add(36, "fx_stages", "FX Stages", "f", 0, 100, 20, 1, " %")   # percent of the 100-stage cap (0 % = 1 stage)
add(37, "fx_mix", "Color Mix", "f", 0, 100, 100, 1, " %")  # wet / dry of the whole colour fx
add(38, "tile", "Tile", "int", 0, 2, 0)
add(39, "morph_dir", "Morph Mode", "int", 0, 2, 2)  # 0 A>B, 1 B>A (detector), 2 MIX (static crossfade by depth)
add(40, "morph_depth", "Morph Depth", "f", 0, 100, 0, 1, " %")
add(41, "morph_speed", "Morph Speed", "f", 0, 100, 50, 1, " %")
add(42, "ab", "Scene A/B", "int", 0, 1, 0)
add(44, "shape_b", "Shape B", "int", 0, 14, 0)     # scene B (scene A: shape, custom curve, tile)
add(45, "tile_b", "Tile B", "int", 0, 2, 0)
# colour fx beyond the diffusor (phaser / flanger / ring modulator share these; the editor relabels them per fx type)
add(46, "fx_rate", "FX Rate", "f", 0.02, 20, 0.5, 0.01, " Hz")      # LFO rate
add(47, "fx_depth", "FX Depth", "f", 0, 100, 50, 1, " %")            # sweep depth / ringmod amount
add(48, "fx_fb", "FX Feedback", "f", -95, 95, 0, 1, " %")            # phaser / flanger feedback
add(49, "fx_delay", "FX Delay", "f", 0.1, 10, 2, 0.01, " ms")        # flanger centre delay
add(50, "fx_shape", "FX Shape", "int", 0, 3, 0)                      # ring modulator carrier: sine / triangle / square / saw
SKEW = {}  # host ranges stay linear: the editor tapers RATE and DELAY (log) itself, like FREQ
# scene B's waveshaper module (scene A's are slots 1-6; the editor addresses the viewed scene)
add(51, "drive_b", "Drive B", "f", 0, 100, 0, 0.1, " %")
add(52, "bias_b", "Bias B", "f", -100, 100, 0, 0.1, " %")
add(53, "sat_hp_b", "Sat HP B", "f", 20, 2000, 20, 1, " Hz")
add(54, "sat_lp_b", "Sat LP B", "f", 200, 20000, 20000, 1, " Hz")
add(55, "tone_b", "Tone B", "f", 1000, 20000, 20000, 1, " Hz")
add(56, "fx_shift", "FX Shift", "f", -1000, 1000, 0, 0.1, " Hz")        # frequency shifter: bipolar shift, the editor tapers it
add(57, "out_hp", "Out HP", "f", 20, 2000, 20, 1, " Hz")        # 24 dB/oct high-pass before OUT GAIN (20 Hz = off)
add(58, "out_hp_m", "Out HP Mid", "bool", 0, 1, 1)
add(59, "out_hp_s", "Out HP Side", "bool", 0, 1, 1)
add(60, "fx_hp", "FX HP", "f", 20, 2000, 20, 1, " Hz")           # HPF / LPF on the wet signal of RINGMOD and FREQ SHIFT
add(61, "fx_lp", "FX LP", "f", 200, 20000, 20000, 1, " Hz")
add(43, "fx_spread", "FX Spread", "f", 0, 100, 50, 1, " %")  # fans the diffusor stages out over up to 8 octaves around FREQ

def f(x):
    return repr(float(x))

o = []
o.append("// GENERATED by tools/gen_dparams.py. Do not edit by hand.\n")
o.append("use nih_plug::prelude::*;\nuse nih_plug_egui::EguiState;\nuse satcomp_dsp::shapers::{asym_from, Curve, SHAPER_COUNT};\nuse satdiff_dsp::DiffParams;\nuse std::sync::atomic::{AtomicBool, AtomicI32};\nuse std::sync::Arc;\n")
o.append("/// Highest UI slot number + 1.\npub const SLOTS: usize = %d;\n" % (max(p[0] for p in P) + 1))
o.append("/// (slot number, id, min, max, default) for every parameter.")
o.append("pub const TABLE: &[(usize, &str, f32, f32, f32)] = &[")
for n, i, name, k, mn, mx, df, st, u in P:
    o.append(f'    ({n}, "{i}", {f(mn)}, {f(mx)}, {f(df)}),')
o.append("];\n")
o.append("#[derive(Params)]\npub struct SatDiffParams {")
o.append('    #[persist = "editor-state"]\n    pub editor_state: Arc<EguiState>,')
o.append('    /// Colour scheme index in the palette table (-1 = not set yet); UI-only, saved with the project.\n    #[persist = "palette-v2"]\n    pub palette_v2: Arc<AtomicI32>,')
o.append('    /// Light mode (the inverted palette of the scheme); UI-only, saved with the project.\n    #[persist = "light-mode"]\n    pub light: Arc<AtomicBool>,')
o.append('    /// Scope fill: true = solid UI-colour bars, false = outline stroke along the peaks; UI-only.\n    #[persist = "fft-solid"]\n    pub fft_solid: Arc<AtomicBool>,')
o.append('    /// UI font index (see `satcomp_ui::canvas::FONT_NAMES`); UI-only, saved with the project.\n    #[persist = "ui-font"]\n    pub font: Arc<AtomicI32>,')
o.append('    /// Active user colour theme (`name|` + 18 hex digits) so a project keeps its look on a machine without the themes file.\n    #[persist = "custom-theme"]\n    pub custom_theme: Arc<parking_lot::Mutex<String>>,')
o.append('    /// Packed scope view settings (see gui/ui/scope.rs); UI-only, saved with the project.\n    #[persist = "scope-v3"]\n    pub scope: Arc<AtomicI32>,')
o.append('    /// Name of the last loaded/saved preset (display only).\n    #[persist = "preset-name"]\n    pub preset_name: Arc<parking_lot::Mutex<String>>,')
o.append('    /// User-drawn waveshaper curve (points on [-1,1]^2, shaper 14 "Custom"); saved with the project and presets.\n    #[persist = "custom-curve"]\n    pub custom_curve: Arc<parking_lot::Mutex<Vec<(f32, f32)>>>,')
o.append('    /// Curve handles and the LINEAR | CURVE choice of scene A\'s drawn curve: `[linear, bend of segment 0, ...]`, empty = plain (`Curve::ext`).\n    #[persist = "custom-curve-ext"]\n    pub custom_curve_ext: Arc<parking_lot::Mutex<Vec<f32>>>,')
o.append('    /// Same for scene B.\n    #[persist = "custom-curve-ext-b"]\n    pub custom_curve_ext_b: Arc<parking_lot::Mutex<Vec<f32>>>,')
o.append('    /// Scene B\'s drawn curve (same format as `custom_curve`).\n    #[persist = "custom-curve-b"]\n    pub custom_curve_b: Arc<parking_lot::Mutex<Vec<(f32, f32)>>>,')
o.append('    /// ASYM per waveshaper (0..100 %, index = shaper); saved with the project and presets (absent = all 100 %).\n    #[persist = "asym"]\n    pub asym: Arc<parking_lot::Mutex<Vec<f32>>>,')
o.append('    /// Scene B\'s ASYM per waveshaper (same format).\n    #[persist = "asym-b"]\n    pub asym_b: Arc<parking_lot::Mutex<Vec<f32>>>,')
for n, i, name, k, mn, mx, df, st, u in P:
    o.append(f'    #[id = "{i}"]\n    pub {i}: {"IntParam" if k=="int" else "BoolParam" if k=="bool" else "FloatParam"},')
o.append("}\n")
o.append("impl Default for SatDiffParams {\n    /// A new instance starts from the shared defaults file (the host then restores a saved project's own look over this).\n    fn default() -> Self {\n        Self::from_defaults(satcomp_ui::appearance::load_defaults_for(\"satdiff\"))\n    }\n}\n")
o.append("impl SatDiffParams {\n    pub fn from_defaults(d: Option<satcomp_ui::appearance::Defaults>) -> Self {\n        Self {")
o.append("            editor_state: {\n                let (w, h) = d.as_ref().map(|d| d.size((316.0, 556.0))).unwrap_or((316, 556));\n                EguiState::from_size(w, h)\n            },")
o.append("            palette_v2: Arc::new(AtomicI32::new(d.as_ref().map(|d| d.pal_index()).unwrap_or(-1))),")
o.append("            light: Arc::new(AtomicBool::new(d.as_ref().map(|d| d.light).unwrap_or(false))),")
o.append("            font: Arc::new(AtomicI32::new(d.as_ref().map(|d| d.face_index()).unwrap_or(0))),")
o.append("            fft_solid: Arc::new(AtomicBool::new(d.as_ref().map(|d| d.fill_solid).unwrap_or(true))),")
o.append("            scope: Arc::new(AtomicI32::new((5 << 4) | (8 << 8))),")
o.append("            custom_theme: Arc::new(parking_lot::Mutex::new(d.as_ref().map(|d| d.theme.clone()).unwrap_or_default())),")
o.append("            preset_name: Arc::new(parking_lot::Mutex::new(String::new())),")
o.append("            custom_curve: Arc::new(parking_lot::Mutex::new(vec![(-1.0, -1.0), (1.0, 1.0)])),")
o.append("            custom_curve_ext: Arc::new(parking_lot::Mutex::new(Vec::new())),")
o.append("            custom_curve_ext_b: Arc::new(parking_lot::Mutex::new(Vec::new())),")
o.append("            custom_curve_b: Arc::new(parking_lot::Mutex::new(vec![(-1.0, -1.0), (1.0, 1.0)])),")
o.append("            asym: Arc::new(parking_lot::Mutex::new(Vec::new())),")
o.append("            asym_b: Arc::new(parking_lot::Mutex::new(Vec::new())),")
for n, i, name, k, mn, mx, df, st, u in P:
    if k == "int":
        o.append(f'            {i}: IntParam::new("{name}", {int(df)}, IntRange::Linear {{ min: {int(mn)}, max: {int(mx)} }}),')
    elif k == "bool":
        o.append(f'            {i}: BoolParam::new("{name}", {"true" if df else "false"}),')
    else:
        rng = f"FloatRange::Skewed {{ min: {f(mn)}, max: {f(mx)}, factor: FloatRange::skew_factor({f(SKEW[i])}) }}" if i in SKEW else f"FloatRange::Linear {{ min: {f(mn)}, max: {f(mx)} }}"
        s = f'            {i}: FloatParam::new("{name}", {f(df)}, {rng})'
        if u: s += f'.with_unit("{u}")'
        if st: s += f'.with_step_size({f(st)})'
        o.append(s + ",")
o.append("        }\n    }\n}\n")
o.append("impl SatDiffParams {")
o.append("    /// Sanitised copy of the persisted custom curve (the UI holds this lock only for a point edit).\n    pub fn curve_snapshot(&self) -> Curve {\n        Curve::from_parts(&self.custom_curve.lock(), &self.custom_curve_ext.lock())\n    }\n\n    /// Scene B's drawn curve.\n    pub fn curve_snapshot_b(&self) -> Curve {\n        Curve::from_parts(&self.custom_curve_b.lock(), &self.custom_curve_ext_b.lock())\n    }\n\n    /// The drawn curve of scene `ab`.\n    pub fn curve_of(&self, ab: i32) -> Curve {\n        if ab == 1 {\n            self.curve_snapshot_b()\n        } else {\n            self.curve_snapshot()\n        }\n    }\n\n    /// Store the drawn curve of scene `ab` (points and handles).\n    pub fn store_curve(&self, ab: i32, c: &Curve) {\n        let (pts, ext) = if ab == 1 { (&self.custom_curve_b, &self.custom_curve_ext_b) } else { (&self.custom_curve, &self.custom_curve_ext) };\n        *pts.lock() = c.pts().to_vec();\n        *ext.lock() = c.ext();\n    }\n\n    /// The drawn curve of scene `ab` (0 = A, 1 = B).\n    pub fn curve_cell(&self, ab: i32) -> &Arc<parking_lot::Mutex<Vec<(f32, f32)>>> {\n        if ab == 1 {\n            &self.custom_curve_b\n        } else {\n            &self.custom_curve\n        }\n    }\n")
o.append("    /// ASYM per shaper, sanitised (short / missing = 100 %).\n    pub fn asym_snapshot(&self) -> [f64; SHAPER_COUNT] {\n        asym_from(&self.asym.lock())\n    }\n\n    /// Scene B's ASYM per shaper, sanitised.\n    pub fn asym_snapshot_b(&self) -> [f64; SHAPER_COUNT] {\n        asym_from(&self.asym_b.lock())\n    }\n\n    /// The ASYM cell of scene `ab`.\n    pub fn asym_cell(&self, ab: i32) -> &Arc<parking_lot::Mutex<Vec<f32>>> {\n        if ab == 1 {\n            &self.asym_b\n        } else {\n            &self.asym\n        }\n    }\n")
o.append("    /// Snapshot for the DSP engine (UI side: may wait briefly for the curve lock).\n    pub fn to_dsp(&self) -> DiffParams {\n        self.to_dsp_with([self.curve_snapshot(), self.curve_snapshot_b()], [self.asym_snapshot(), self.asym_snapshot_b()])\n    }\n")
o.append("    /// Audio-thread snapshot: never blocks on the curve lock. While the UI holds it the previous curve is reused.\n    pub fn to_dsp_rt(&self, last: &mut [Curve; 2], last_asym: &mut [[f64; SHAPER_COUNT]; 2]) -> DiffParams {\n        if let (Some(g), Some(e)) = (self.custom_curve.try_lock(), self.custom_curve_ext.try_lock()) {\n            last[0] = Curve::from_parts(&g, &e);\n        }\n        if let (Some(g), Some(e)) = (self.custom_curve_b.try_lock(), self.custom_curve_ext_b.try_lock()) {\n            last[1] = Curve::from_parts(&g, &e);\n        }\n        if let Some(g) = self.asym.try_lock() {\n            last_asym[0] = asym_from(&g);\n        }\n        if let Some(g) = self.asym_b.try_lock() {\n            last_asym[1] = asym_from(&g);\n        }\n        self.to_dsp_with(*last, *last_asym)\n    }\n")
o.append("    fn to_dsp_with(&self, curves: [Curve; 2], asyms: [[f64; SHAPER_COUNT]; 2]) -> DiffParams {")
o.append("        DiffParams {")
o.append("            shape: self.shape.value(), curve: curves[0], curve_b: curves[1], shape_b: self.shape_b.value(), tile_b: self.tile_b.value(), asym: asyms[0], asym_b: asyms[1], drive_b: self.drive_b.value() as f64, bias_b: self.bias_b.value() as f64, sat_hp_b: self.sat_hp_b.value() as f64, sat_lp_b: self.sat_lp_b.value() as f64, tone_b: self.tone_b.value() as f64, drive: self.drive.value() as f64, bias: self.bias.value() as f64,")
o.append("            sat_hp: self.sat_hp.value() as f64, sat_lp: self.sat_lp.value() as f64, tone: self.tone.value() as f64,")
o.append("            sat_mix: self.sat_mix.value() as f64, in_gain: self.in_gain.value() as f64, os: self.os.value(),")
o.append("            out_gain: self.out_gain.value() as f64, gain_match: self.gain_match.value(), lim_on: self.lim_on.value(),")
o.append("            bypass: self.bypass.value(), ab: self.ab.value(), phase: self.phase.value() as f64, fx_on: self.fx_on.value(),")
o.append("            fx_type: self.fx_type.value(), fx_pos: self.fx_pos.value(), fx_freq: self.fx_freq.value() as f64, fx_q: self.fx_q.value() as f64,")
o.append("            fx_stages: satdiff_dsp::diffuse::stages_from_pct(self.fx_stages.value() as f64), fx_spread: self.fx_spread.value() as f64, fx_rate: self.fx_rate.value() as f64, fx_depth: self.fx_depth.value() as f64, fx_fb: self.fx_fb.value() as f64, fx_delay: self.fx_delay.value() as f64, fx_shape: self.fx_shape.value(), fx_shift: self.fx_shift.value() as f64, fx_hp: self.fx_hp.value() as f64, fx_lp: self.fx_lp.value() as f64, out_hp: self.out_hp.value() as f64, out_hp_m: self.out_hp_m.value(), out_hp_s: self.out_hp_s.value(), fx_mix: self.fx_mix.value() as f64, tile: self.tile.value(), morph_dir: self.morph_dir.value(),")
o.append("            morph_depth: self.morph_depth.value() as f64, morph_speed: self.morph_speed.value() as f64,")
o.append("        }\n    }\n")
o.append("    /// Parameter by slot number (UI addressing).\n    pub fn ptr(&self, n: usize) -> Option<ParamPtr> {\n        Some(match n {")
for n, i, *_ in P:
    o.append(f"            {n} => self.{i}.as_ptr(),")
o.append("            _ => return None,\n        })\n    }\n}")
import os
os.makedirs("satdiff-plugin/src", exist_ok=True)
open("satdiff-plugin/src/params.rs", "w").write("\n".join(o) + "\n")
print(len(P), "params")
